import {ROLES,STEPS,STEP_ROLE,iso,today,sha256,esc,makeId,makeLot,seed,seedCertified,audit,lastAttempt,nextStep,statusLot,inspect,handoff,issueCertificate,certificateStatus,setHold,relatedMeals,clean} from './engine.mjs?v=5.2.1';
import {analyzeTemperature,classifyComplaint,matchOCR,fuseEvidence} from './ai.mjs';
import {createPassport,qrSVG,qrAsSVGFile} from './passport.mjs';

const STORAGE='safemeal_v5_individual_demo';const $=(s)=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=ts=>ts?new Date(ts).toLocaleString('vi-VN',{dateStyle:'short',timeStyle:'short'}):'—';
const PAGES={overview:['◫','Tổng quan'],lots:['▤','Quản lý lô'],workflow:['◈','Kiểm định 3 bước'],ai:['✧','AI Inspection Lab'],passports:['▦','Hộ chiếu & QR'],incidents:['⚑','Phản ánh và thu hồi'],audit:['⌁','Nhật ký minh bạch'],wallet:['⬡','Kết nối ví Web3']};
let db=seed(),page='overview',activeLot='L003',role='farm',aiCSV='',aiSrc='mẫu minh họa',aiResult=null,aiNLP=null,aiOCR=null,aiImage=null,aiRef=null,aiModelResult=null,aiOCRText='',aiNarrative='Nhiệt độ trong vận chuyển có lúc tăng cao, cần kiểm tra lại niêm phong.',wallet=null;
let latestPassport=null;let toastTimer=0;
const aiSeriesFor=(l,kind='normal')=>{const max=Number(l.threshold),b=Math.min(max-1.2,Math.max(-7,max-3.5));const n=kind==='alert'?[b,b+.4,max+.8,max+2.5,max+3.2,max+1.5,b+.3,b]:kind==='outlier'?[b,b+.1,b+.2,b+.1,b-4.1,b+.2,b+.1,b+.3]:[b,b+.2,b-.1,b+.3,b+.1,b+.2,b,b+.1];return n.map((v,i)=>`${String(8+Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'},${v.toFixed(1)}`).join('\n')};
function resetAnalysis(l){aiCSV=aiSeriesFor(l);aiSrc='Mẫu nhiệt độ theo ngưỡng của '+l.id;aiResult=null;aiNLP=null;aiOCR=null;aiModelResult=null;aiOCRText='';if(aiImage?.url)URL.revokeObjectURL(aiImage.url);if(aiRef?.url)URL.revokeObjectURL(aiRef.url);aiImage=null;aiRef=null;latestPassport=null;}
function chooseLot(id,target='workflow'){const l=byId(id);if(!l)throw Error('Lô không tồn tại: '+id);activeLot=l.id;db.active=l.id;sessionStorage.setItem('safemeal_v5_active',l.id);resetAnalysis(l);save();page=target;render();}

const examples={normal:'08:00,4.1\n08:30,4.3\n09:00,4.2\n09:30,4.6\n10:00,4.3\n10:30,4.5\n11:00,4.2\n11:30,4.1',alert:'08:00,4.1\n08:30,4.6\n09:00,5.0\n09:30,11.5\n10:00,12.1\n10:30,10.4\n11:00,5.5\n11:30,4.2',outlier:'08:00,4.0\n08:30,4.1\n09:00,4.2\n09:30,4.1\n10:00,0.4\n10:30,4.2\n11:00,4.1\n11:30,4.3'};
function getLot(){return db.lots.find(x=>x.id===activeLot)||db.lots[0]};
function byId(id){return db.lots.find(x=>x.id===id)};
function save(){try{db.active=activeLot;localStorage.setItem(STORAGE,JSON.stringify(db));const check=JSON.parse(localStorage.getItem(STORAGE)||'null');if(!check||!Array.isArray(check.lots)||!check.lots.some(x=>x.id===activeLot))throw Error('Không đọc lại được lô đã lưu');return true}catch(e){console.error(e);showToast('Không thể lưu vào trình duyệt. Hãy xuất sao lưu JSON, kiểm tra dung lượng bộ nhớ hoặc trình duyệt ẩn danh.',true);return false}}
async function init(){try{const x=JSON.parse(localStorage.getItem(STORAGE)||'null');if(x?.version===5&&Array.isArray(x.lots))db=x;else{await seedCertified(db);save()}}catch(e){console.warn(e);db=seed();await seedCertified(db);save()}let selected=null;try{selected=sessionStorage.getItem('safemeal_v5_active')}catch(e){console.warn('Session storage unavailable',e)}selected=selected||db.active;if(byId(selected))activeLot=selected;else activeLot=db.lots[0]?.id||'L003';resetAnalysis(getLot());render();}
function showToast(msg,err=false){const box=$('#toast-layer');box.innerHTML=`<div class="toast ${err?'err':''}">${esc(msg)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.innerHTML='',5000)}
function btn(text,cmd,id='',cl=''){return `<button class="btn ${cl}" type="button" data-action="${esc(cmd)}" data-id="${esc(id)}">${text}</button>`;}
function badge(level){const obj={valid:['✓ Được ghi nhận','pill-success'],certified:['✓ Đã có mã','pill-success'],ready:['✓ Đã đủ 3 bước','pill-success'],pending:['◷ Đang kiểm định','pill-neutral'],fail:['✕ Không đạt','pill-danger'],pass:['✓ Đạt','pill-success'],high:['● Cảnh báo cao','pill-danger'],medium:['◐ Cần xem xét','pill-warning'],low:['● Nguy cơ thấp','pill-success'],held:['⏸ Đang tạm giữ','pill-danger'],expired:['⚠ Hết hạn','pill-danger']};const x=obj[level]||[level,'pill-neutral'];return `<span class="pill ${x[1]}">${x[0]}</span>`;}
function heading(kicker,title,detail,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${detail}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function layout(html){$('#app').innerHTML=html;$('#navigation').innerHTML=Object.entries(PAGES).map(([id,v])=>`<button class="nav-btn ${page===id?'active':''}" data-page="${id}"><span>${v[0]}</span>${v[1]}</button>`).join('');$('#crumb').textContent=PAGES[page][1];}
function selectLots(){return `<select id="lot-select" class="input lot-selector">${db.lots.map(l=>`<option value="${esc(l.id)}" ${l.id===activeLot?'selected':''}>${esc(l.id)} · ${esc(l.name)}</option>`).join('')}</select>`;}
function roleSelect(){return `<select id="role-select" class="input" style="width:auto;min-width:174px">${Object.entries(ROLES).map(([id,x])=>`<option value="${id}" ${role===id?'selected':''}>${esc(x)}</option>`).join('')}</select>`;}
function stepBox(l,n){const last=lastAttempt(l,n);const state=last?.result==='pass'?'done':last?.result==='fail'?'failed':'';let msg=last?`${esc(last.actor==='farm'?'Nông trại':last.actor==='factory'?'Nhà máy':'Điểm bán')} · ${fmt(last.time)}`:'Chưa thực hiện';return `<div class="step ${state}"><span class="glyph">${['','🌱','🏭','🏪'][n]}</span><div class="step-number">GIAI ĐOẠN 0${n}</div><h3>${esc(STEPS[n])}</h3><p>${msg}</p>${badge(last?.result||'pending')}${last?.result==='fail'?'<p style="margin-top:9px;color:#bc4f3f">Cần khắc phục và kiểm định lại</p>':''}</div>`;}
function lotRow(l){const s=certificateStatus(l),n=nextStep(l);return `<tr><td><div class="product-cell"><span class="product-emoji">${l.name.toLowerCase().includes('sữa')?'🥛':l.name.toLowerCase().includes('thịt')||l.name.toLowerCase().includes('gà')?'🍗':l.name.toLowerCase().includes('rau')?'🥬':'📦'}</span><div><b>${esc(l.name)}</b><small>${esc(l.id)} · ${esc(l.origin)}</small></div></div></td><td>${l.threshold}°C</td><td>${n===4?'3 / 3':n-1+' / 3'}</td><td>${l.certificate?badge(s.level):badge(statusLot(l))}</td><td>${btn('Mở hồ sơ','open-lot',l.id,'small')}</td></tr>`;}
function renderOverview(){const l=getLot();layout(`<div class="hero"><div class="hero-content"><div class="eyebrow">SAFEMEAL V5 • DIGITAL FOOD PASSPORT</div><h1>Từ nông trại đến bàn ăn.<br>Một hành trình kiểm định minh bạch.</h1><p>Kiểm định 3 giai đoạn, AI hỗ trợ phát hiện rủi ro, mã QR mở được trên điện thoại khác. Mọi quyết định đều có lý do và lịch sử.</p><div class="actions">${btn('＋ Tạo lô thực tế','new-lot','','primary')}${btn('▤ Quản lý '+db.lots.length+' lô','goto','lots')}${btn('▦ Xem hộ chiếu mẫu','open-lot','L001')}</div></div><div class="hero-art">🥕</div></div><div class="cards four" style="margin-bottom:19px"><div class="stat-card"><div class="top"><span>Lô nguyên liệu</span><span class="icon">📦</span></div><strong>${db.lots.length}</strong><small>Đang được theo dõi</small></div><div class="stat-card"><div class="top"><span>Mã hộ chiếu đã cấp</span><span class="icon">▦</span></div><strong>${db.lots.filter(l=>l.certificate).length}</strong><small>Có thể mở bằng QR</small></div><div class="stat-card"><div class="top"><span>Phiếu kiểm định</span><span class="icon">◈</span></div><strong>${db.lots.reduce((n,l)=>n+l.inspections.length,0)}</strong><small>Gồm cả lần không đạt</small></div><div class="stat-card"><div class="top"><span>Phản ánh & tạm giữ</span><span class="icon">⚑</span></div><strong>${db.complaints.length} / ${db.lots.filter(l=>l.held).length}</strong><small>Đánh giá theo từng lô</small></div></div><div class="two-col"><section class="surface"><div class="section-head"><h2>Hành trình một lô sản phẩm</h2>${btn('Làm kiểm định','goto','workflow','small')}</div><div class="steps">${[1,2,3].map(n=>stepBox(l,n)).join('')}</div><div class="notice" style="margin-top:17px">${l.certificate?`Mã <b>${esc(l.certificate.code)}</b> đã sẵn sàng. Quét QR để xem thông tin trên điện thoại khác.`:`Lô <b>${esc(l.id)}</b> cần hoàn tất giai đoạn ${nextStep(l)}. Các trạng thái “Không đạt” có thể khắc phục và kiểm định lại.`}</div></section><section class="surface"><div class="section-head"><h2>Hướng dẫn demo nhanh</h2><span class="pill pill-neutral">3 phút</span></div><div class="timeline"><div class="tl-entry"><span class="tl-dot">1</span><div class="tl-body"><strong>Kiểm định nguồn gốc, nhà máy</strong><p>Thực hiện đúng vai trò, có đường trả về khi không đạt.</p></div></div><div class="tl-entry"><span class="tl-dot">2</span><div class="tl-body"><strong>Nhận hàng và phân tích AI</strong><p>Tải CSV thật hoặc chọn dữ liệu minh họa.</p></div></div><div class="tl-entry"><span class="tl-dot">3</span><div class="tl-body"><strong>Cấp mã và quét QR</strong><p>Dùng điện thoại khác mở hộ chiếu mà không cần đăng nhập.</p></div></div></div>${btn('Tiếp tục lô '+esc(l.id),'goto','workflow','primary')} ${btn('＋ Tạo lô riêng','new-lot')} ${btn('Khôi phục dữ liệu mẫu','reset','','small')}</section></div><section class="surface" style="margin-top:18px"><div class="section-head"><h2>Các lô trong hệ thống</h2>${btn('＋ Tạo lô mới','new-lot')} ${btn('Quản lý toàn bộ lô','goto','lots','small')}</div><div class="table-wrap"><table class="tbl"><thead><tr><th>SẢN PHẨM</th><th>NGƯỠNG</th><th>TIẾN ĐỘ</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${db.lots.map(lotRow).join('')}</tbody></table></div></section>`);}
function renderLots(){const lastNew=byId(db.lastCreatedLot);const rows=db.lots.map(l=>{const step=nextStep(l),done=!!l.certificate;return `<tr data-lot-id="${esc(l.id)}" style="${l.id===db.lastCreatedLot?'background:#e9f9ef;border-left:4px solid #16805d;':''}"><td><strong>${esc(l.id)}</strong><small style="display:block">${esc(l.name)} · ${esc(l.origin)}</small></td><td>${esc(l.qty)} ${esc(l.unit)}</td><td>${esc(l.threshold)}°C</td><td>${done?badge(certificateStatus(l).level):badge(statusLot(l))}<div class="micro">${done?'Đã có hộ chiếu':`Tiếp theo: bước ${step}/3`}</div></td><td><div class="actions">${btn('Kiểm định','open-lot',l.id,'small')}${btn('AI','lot-to-ai',l.id,'small')}${btn('QR','lot-to-passport',l.id,'small')}${btn('Phản ánh','lot-to-incident',l.id,'small')}</div></td></tr>`}).join('');layout(`${heading('QUẢN LÝ NGUỒN NGUYÊN LIỆU','Toàn bộ lô sản phẩm','Mọi lô mới tạo đều nằm ở đây và được dùng xuyên suốt kiểm định, AI, mã QR, phản ánh, nhật ký.','')}
${lastNew?`<div class="notice" id="new-lot-confirmation" style="background:#e8f8ec;border:1px solid #7cbd95;margin-bottom:16px"><b>✓ ĐÃ LƯU LÔ MỚI: ${esc(lastNew.id)} — ${esc(lastNew.name)}</b><p>Lô đã được ghi vào bộ nhớ trình duyệt và nằm ở hàng được tô màu trong bảng bên dưới. Nhấn nút để thực hiện kiểm định bước 1 hoặc vào phòng AI.</p><div class="actions">${btn('▶ Kiểm định lô '+lastNew.id,'open-lot',lastNew.id,'primary')}${btn('✧ Phân tích AI lô này','lot-to-ai',lastNew.id)}</div></div>`:''}<div class="toolbar"><div class="filter-row"><b>${db.lots.length} lô đang lưu trên trình duyệt</b></div><div class="actions">${btn('＋ Tạo lô mới','new-lot','','primary')}${btn('Xuất bản sao lưu JSON','export-json')}${btn('Nhập lại bản sao lưu','import-json')}</div></div>
<div class="notice"><b>Quy trình cho lô mới:</b> Tạo lô → kiểm định nguồn gốc → nhà máy → nhận hàng → lưu báo cáo AI → kiểm định tại điểm bán → cấp QR. <b>Dữ liệu được lưu trong trình duyệt này.</b> Để chuyển sang máy khác, hãy xuất/nhập JSON; mã QR tự chứa thông tin hộ chiếu đã cấp nhưng không đồng bộ trạng thái theo thời gian thực.</div>
<section class="surface" style="margin-top:15px"><div class="table-wrap"><table class="tbl"><thead><tr><th>LÔ / TÊN / XUẤT XỨ</th><th>SỐ LƯỢNG</th><th>NGƯỠNG</th><th>TIẾN ĐỘ</th><th>THAO TÁC</th></tr></thead><tbody>${rows}</tbody></table></div></section>`)}
function renderWorkflow(){const l=getLot(),next=nextStep(l),last=next<=3?lastAttempt(l,next):null,needed=STEP_ROLE[next],eligible=role===needed,failed=last?.result==='fail';layout(`${heading('QUY TRÌNH NGHIỆP VỤ','Kiểm định 3 giai đoạn','Hoàn thành đúng thứ tự, lưu lịch sử mỗi lần kiểm định và lý do khắc phục. Chỉ cấp mã khi cả 3 giai đoạn Đạt và điểm bán đã tiếp nhận.','')}
<div class="toolbar"><div class="filter-row"><b>Chọn lô:</b>${selectLots()}${btn('＋ Lô mới','new-lot','','small')}</div><div class="filter-row"><span class="micro">Đang thao tác với vai trò</span>${roleSelect()}</div></div>
${failed?`<div class="notice danger"><b>✕ Bước ${next} không đạt — đang chờ khắc phục</b><p>Lý do: ${esc(last.notes)}. Trả về <b>${esc(ROLES[needed])}</b>, ghi biện pháp khắc phục và kiểm định lại. Phiếu không đạt cũ vẫn lưu trong lịch sử.</p></div>`:''}
<div class="notice ${failed?'danger':'next===4'?'':' '}">${next===4?'✓ Đã hoàn thành đủ ba bước.':`<b>Bước cần thực hiện: ${next}/3 — ${esc(STEPS[next])}</b><p>${next===3&&!l.handoff?'Cần điểm bán xác nhận nhận hàng trước khi ghi phiếu bước 3.':next===3?'Bước 3 cần có báo cáo AI chuỗi lạnh sau khi bàn giao.':`Vai trò phụ trách: ${esc(ROLES[needed])}.`}</p>`}
<div class="actions" style="margin-top:9px">${next<=3&&role!==needed?btn('Đổi sang '+ROLES[needed],'set-role',needed,'primary'):next===3&&!l.handoff?btn('✓ Điểm bán xác nhận nhận hàng','handoff','','primary'):next===3&&!l.aiReports.some(r=>r.stage===3&&r.created>=l.handoff?.time)?btn('✧ Phân tích AI trước bước 3','goto','ai','primary'):next<=3?btn(failed?'↻ Khắc phục và kiểm định lại':'＋ Ghi phiếu kiểm định bước '+next,'inspect','','primary'):btn('▦ Xem và xuất hộ chiếu','goto','passports','primary')}${next===3&&l.handoff?btn('Mở phòng lab AI','goto','ai'):''}</div></div>
<div class="steps" style="margin:17px 0">${[1,2,3].map(n=>stepBox(l,n)).join('')}</div><div class="two-col"><section class="surface"><div class="section-head"><h2>Thông tin lô ${esc(l.id)}</h2>${badge(l.certificate?certificateStatus(l).level:statusLot(l))}</div><div class="cards two"><div class="muted-panel"><b>Sản phẩm</b><p>${esc(l.name)}</p></div><div class="muted-panel"><b>Xuất xứ</b><p>${esc(l.origin)}</p></div><div class="muted-panel"><b>Số lượng</b><p>${l.qty} ${esc(l.unit)}</p></div><div class="muted-panel"><b>Ngưỡng nhiệt</b><p>${l.threshold}°C</p></div></div><div class="divider"></div><h3>Điều kiện cần hoàn thành</h3><div class="stack">${[1,2,3].map(n=>`<div class="check-row"><span>${lastAttempt(l,n)?.result==='pass'?'✅':lastAttempt(l,n)?.result==='fail'?'❌':'◯'}</span><div><b>${esc(STEPS[n])}</b><div class="micro">${lastAttempt(l,n)?.result==='pass'?'Đã có phiếu Đạt':lastAttempt(l,n)?.result==='fail'?'Cần kiểm định lại':'Chưa thực hiện'}</div></div></div>`).join('')}<div class="check-row"><span>${l.handoff?'✅':'◯'}</span><div><b>Phiếu bàn giao tại điểm bán</b><div class="micro">${l.handoff?fmt(l.handoff.time):'Chưa nhận hàng'}</div></div></div><div class="check-row"><span>${l.aiReports.filter(x=>x.stage===3&&x.created>=l.handoff?.time).length?'✅':'◯'}</span><div><b>Báo cáo AI hỗ trợ bước 3</b><div class="micro">Phải được lập sau khi nhận hàng.</div></div></div></div></section><section class="surface"><div class="section-head"><h2>Nhật ký kiểm định & khắc phục</h2><span class="micro">${l.inspections.length} lượt ghi</span></div>${l.inspections.length?`<div class="timeline">${[...l.inspections].reverse().map(x=>`<div class="tl-entry ${x.result==='fail'?'fail':''}"><span class="tl-dot">${x.result==='pass'?'✓':'✕'}</span><div class="tl-body"><strong>Bước ${x.step}: ${x.result==='pass'?'ĐẠT':'KHÔNG ĐẠT'}</strong><p>${esc(x.location)} · ${fmt(x.time)}</p><p>${esc(x.notes)}</p>${x.correction?`<p style="color:#15765e"><b>Khắc phục:</b> ${esc(x.correction)}</p>`:''}<small class="mono">SHA-256: ${x.digest.slice(0,18)}…</small></div></div>`).join('')}</div>`:'<div class="empty">Chưa có phiếu kiểm định.</div>'}</section></div>`);}
function graphPoints(r){const vals=r.data.map(x=>x.temp),min=Math.min(...vals,r.threshold)-1,max=Math.max(...vals,r.threshold)+1;const y=x=>166-135*(x-min)/(max-min);const x=i=>30+i*(550/Math.max(1,vals.length-1));let points=vals.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');let label=r.data.filter((a,i)=>i%Math.max(1,Math.ceil(vals.length/8))===0).map(a=>`<text x="${x(r.data.indexOf(a))}" y="194" font-size="10" fill="#85958c" text-anchor="middle">${esc(a.time)}</text>`).join('');return `<svg class="data-graph" viewBox="0 0 620 210" role="img" aria-label="Biểu đồ nhiệt độ"><line x1="20" x2="590" y1="${y(r.threshold)}" y2="${y(r.threshold)}" stroke="#dc594e" stroke-dasharray="6 5" stroke-width="2"/><text x="23" y="${y(r.threshold)-9}" font-size="11" fill="#c04438">Giới hạn ${r.threshold}°C</text><polyline fill="none" stroke="#0d9670" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="${points}"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="${v>r.threshold?'5':'3.5'}" fill="${v>r.threshold?'#d75a43':'#0e9872'}"/>`).join('')}${label}</svg>`;}
function aiResultMarkup(){if(!aiResult)return `<div class="notice">Hãy chọn tình huống hoặc tải CSV, sau đó nhấn <b>Chạy phân tích</b> để xem biểu đồ và bằng chứng.</div>`;return `<div class="surface" style="padding:17px"><div class="section-head"><h2>Đánh giá chuỗi lạnh</h2>${badge(aiResult.level)}</div><div class="risk-meter"><div><span class="micro">ĐIỂM SÀNG LỌC</span><div class="risk-num ${aiResult.level==='high'?'high':''}">${aiResult.score}<small style="font-size:13px;font-weight:400">/100</small></div></div><div style="flex:1"><div class="progress"><i style="width:${aiResult.score}%"></i></div><p class="micro" style="margin:8px 0 0">${esc(aiResult.sourceMethod)}</p></div></div>${graphPoints(aiResult)}<div class="cards three"><div class="muted-panel"><b>Cao nhất</b><p>${aiResult.max}°C</p></div><div class="muted-panel"><b>Vượt ngưỡng</b><p>${aiResult.exceed} mốc</p></div><div class="muted-panel"><b>Điểm ngoại lai MAD</b><p>${aiResult.anomalous}</p></div></div><div class="notice ${aiResult.level==='high'?'danger':''}"><b>Kết luận hỗ trợ:</b> ${aiResult.reasons.map(esc).join('; ')}. Đây không phải xét nghiệm an toàn thực phẩm.</div></div>`;}
function renderAI(){const l=getLot();layout(`${heading('MULTI-SIGNAL ANALYTICS','SafeMeal AI Inspection Lab','Đọc dữ liệu cảm biến, phân loại phản ánh và phân tích ảnh bằng mô hình tùy chọn. Mọi nguồn đều hiển thị rõ, AI không tự cấp giấy chứng nhận.','')}
<div class="toolbar"><div class="filter-row"><b>Đánh giá lô:</b>${selectLots()}</div>${btn('⚡ Chạy dữ liệu bình thường','sample','normal','primary')}${btn('⚠ Đứt chuỗi lạnh','sample','alert')}${btn('⌁ Điểm ngoại lai','sample','outlier')}</div><div class="evidence"><section class="surface"><div class="section-head"><h2>01. Phân tích chuỗi lạnh</h2><span class="pill pill-neutral">Ngưỡng ${l.threshold}°C</span></div><p class="micro">CSV thời gian,nhiệt độ — tối đa 1.500 mốc. Tự tính MAD, số lần vượt và chuỗi liên tục.</p><label class="field"><span class="micro"><b>Tải CSV hoặc TXT từ máy</b></span><input id="csv-file" type="file" accept=".csv,.txt,text/plain,text/csv" class="input-file"/></label><div class="file-status">Nguồn hiện tại: <b>${esc(aiSrc)}</b></div><label class="field" style="margin-top:9px"><span class="micro">Số đo (thời gian,nhiệt độ °C)</span><textarea id="csv-text" class="input mono" rows="7">${esc(aiCSV)}</textarea></label><div class="actions" style="margin-top:12px">${btn('▶ Phân tích dữ liệu','ai-run','','primary')}${btn('Tải CSV mẫu','demo-csv')}${btn('↩ Trở lại kiểm định','goto','workflow')}</div></section><section class="surface"><div class="section-head"><h2>02. Phân loại phản ánh (NLP)</h2><span class="pill pill-neutral">Naive Bayes</span></div><p class="micro">Bộ học 25 câu minh họa, 5 loại phản ánh. Kết quả chỉ xếp ưu tiên xem xét.</p><label class="field"><span class="micro">Nội dung người mua phản ánh</span><textarea id="ai-narrative" rows="6" class="input">${esc(aiNarrative)}</textarea></label><div class="actions" style="margin-top:12px">${btn('✧ Phân loại phản ánh','ai-nlp','','primary')}${btn('Dùng ví dụ nhãn sai','nlp-example')}</div>${aiNLP?`<div class="notice" style="margin-top:12px"><b>${esc(aiNLP.name)}</b> · chỉ số mô hình ${(aiNLP.confidence*100).toFixed(1)}%<p class="micro">Không phải xác suất kiểm định hay chứng nhận.</p></div>`:''}</section></div><div class="two-col" style="margin-top:17px"><div class="stack">${aiResultMarkup()}<div class="surface"><div class="section-head"><h2>Điểm tổng hợp đa tín hiệu</h2><span class="pill pill-neutral">Risk Fusion</span></div>${aiResult?`<div class="risk-meter"><strong class="risk-num ${fuseEvidence({cold:aiResult,ocr:aiOCR,nlp:aiNLP,similarity:aiModelResult?.similarity??null}).level==='high'?'high':''}">${fuseEvidence({cold:aiResult,ocr:aiOCR,nlp:aiNLP,similarity:aiModelResult?.similarity??null}).score}<small style="font-size:13px">/100</small></strong><div class="micro">Gộp cảnh báo nhiệt độ, sai mã OCR và phản ánh nghi rủi ro. Chỉ số sàng lọc, không phải xác suất an toàn.</div></div><div class="muted-panel">${fuseEvidence({cold:aiResult,ocr:aiOCR,nlp:aiNLP,similarity:aiModelResult?.similarity??null}).reasons.map(esc).join('; ')}</div>`:'<p>Chạy phân tích cảm biến để tính điểm tổng hợp.</p>'}</div><div class="surface"><div class="section-head"><h2>03. Lưu báo cáo bằng chứng</h2><span class="pill pill-neutral">Lưu trong trình duyệt</span></div><p class="micro">Lưu nguồn nhập, chuỗi đo và hash. Bước 3 yêu cầu báo cáo mới sau khi bàn giao tại điểm bán.</p><div class="actions">${btn('✓ Lưu báo cáo AI cho lô '+l.id,'ai-save','','primary')}${role==='inspector'?btn('Xem xét cảnh báo cao','ai-review'):btn('Chuyển vai trò Ban kiểm định','set-role','inspector')}</div><div class="divider"></div><h3>Báo cáo đã ghi (${l.aiReports.length})</h3>${l.aiReports.slice().reverse().slice(0,4).map(r=>`<div class="muted-panel" style="margin-bottom:7px"><b>${fmt(r.created)} · ${r.sourceLabel||r.source}</b><div class="micro">Rủi ro ${r.risk.score}/100 — ${r.risk.level}${r.review?' · ĐÃ XEM XÉT':''}</div></div>`).join('')||'<p>Chưa có báo cáo.</p>'}</div></div><div class="stack"><section class="surface"><div class="section-head"><h2>04. Thị giác máy tính</h2><span class="pill pill-neutral">MobileNet v2</span></div><p class="micro">Mô hình ImageNet pretrained chạy trong trình duyệt, không phải AI chuyên kiểm tra vi khuẩn hay nấm mốc.</p><div class="fields"><label class="field"><span>Ảnh cần kiểm tra</span><input class="input-file" type="file" id="ai-photo" accept="image/jpeg,image/png,image/webp"/></label><label class="field"><span>Ảnh tham chiếu cùng lô</span><input class="input-file" type="file" id="ai-reference" accept="image/jpeg,image/png,image/webp"/></label></div><div class="cards two" style="margin-top:10px"><div>${aiImage?.url?`<img class="preview" src="${aiImage.url}" alt="Ảnh người dùng chọn"/>`:`<img class="preview" src="${l.photo||'assets/carrot-main.jpg'}" alt="Minh họa sản phẩm"/>`}<div class="micro">${aiImage?esc(aiImage.name):'Chưa chọn ảnh thực tế'}</div></div><div>${aiRef?.url?`<img class="preview" src="${aiRef.url}" alt="Ảnh tham chiếu"/>`:`<img class="preview" src="assets/carrot-ref.jpg" alt="Ảnh tham chiếu minh họa"/>`}<div class="micro">${aiRef?esc(aiRef.name):'Chưa chọn ảnh tham chiếu'}</div></div></div><div class="actions" style="margin-top:10px">${btn('Chạy MobileNet','ai-vision','','primary')}${btn('So sánh hai ảnh','ai-compare')}${btn('Nạp ảnh sản phẩm mẫu','image-demo','product')}${btn('Nạp nhãn mẫu','image-demo','label')}</div>${aiModelResult?`<div class="notice"><b>${esc(aiModelResult.title)}</b><p>${esc(aiModelResult.summary)}</p></div>`:''}</section><section class="surface"><div class="section-head"><h2>05. OCR đọc mã lô trên nhãn</h2><span class="pill pill-neutral">Tesseract.js</span></div><p class="micro">Dùng ảnh ở ô “Ảnh cần kiểm tra”; ảnh nhãn sắc nét cho kết quả tốt hơn. Cần Internet lần đầu để tải mô hình.</p><div class="actions">${btn('Đọc OCR từ ảnh đã chọn','ai-ocr','','primary')}${btn('Thử OCR text mẫu đúng','ocr-right')}${btn('Sai mã','ocr-wrong')}</div>${aiOCR?`<div class="notice ${aiOCR.match?'':'danger'}"><b>${esc(aiOCR.status)}</b><p>Nhận thấy: ${esc(aiOCR.found.join(', ')||'(chưa tìm thấy)')}</p><p>Chuỗi OCR: ${esc(aiOCR.text.slice(0,190))}</p></div>`:''}</section></div></div>`);}
function renderPassports(){const l=getLot();layout(`${heading('HỒ SƠ TRUY XUẤT','Hộ chiếu số & QR','Mỗi mã chứa ảnh chụp tối giản của lịch sử ba bước, mở được trên điện thoại khác. Không yêu cầu cùng localStorage hoặc đăng nhập.','')}
<div class="toolbar"><div class="filter-row"><b>Chọn lô:</b>${selectLots()}</div>${btn('Tạo ảnh QR và đường link','qr-generate','','primary')}${btn('Sao chép mã SMKD','copy-code')}</div>
<div class="two-col"><section class="surface"><div class="section-head"><h2>${esc(l.name)}</h2>${l.certificate?badge(certificateStatus(l).level):badge('pending')}</div><div class="cards two"><div class="muted-panel"><b>Mã lô</b><p>${esc(l.id)}</p></div><div class="muted-panel"><b>Xuất xứ</b><p>${esc(l.origin)}</p></div><div class="muted-panel"><b>Hạn dùng</b><p>${esc(l.expiry||'Chưa có')}</p></div><div class="muted-panel"><b>Mã kiểm định</b><p class="mono">${esc(l.certificate?.code||'Chưa cấp')}</p></div></div><div class="divider"></div><h3>Ba phiếu kiểm định mới nhất</h3>${[1,2,3].map(n=>`<div class="pass-step"><span class="check">${lastAttempt(l,n)?.result==='pass'?'✓':'·'}</span><div><b>${esc(STEPS[n])}</b><p>${esc(lastAttempt(l,n)?.location||'Chưa thực hiện')}</p></div></div>`).join('')}<div class="notice warn"><b>Phạm vi xác minh:</b> QR mang nội dung hồ sơ (có checksum SHA-256) để đọc độc lập. Không chống được người cố ý dựng lại một QR khác, không tự đồng bộ tạm giữ/thu hồi sau ngày tạo QR.</div></section><section class="surface"><div class="section-head"><h2>Quét trên điện thoại</h2><span class="pill pill-success">Truy cập không cần đăng nhập</span></div>${l.certificate?`<div id="qr-output"><div class="empty">Nhấn “Tạo ảnh QR và đường link” để xuất hộ chiếu.</div></div><div class="actions" style="margin-top:13px">${btn('Tải QR SVG','qr-download')}${btn('Sao chép link','copy-link')}${btn('Mở hộ chiếu','open-passport','','primary')}</div>`:`<div class="notice warn"><b>Chưa có mã để quét.</b> Hãy hoàn thành đủ 3 bước kiểm định và bàn giao trước khi tạo mã.</div>${btn('Đến trang kiểm định','goto','workflow','primary')}`}</section></div>`);if(l.certificate)qrGenerate({auto:true});}
function renderIncidents(){const l=getLot(),r=relatedMeals(db,l.id);layout(`${heading('SAFETY RESPONSE','Phản ánh và thu hồi','Tiếp nhận phản ánh khách hàng, tự liên kết lô–mẻ ăn, phân loại NLP và lưu quyết định tạm giữ theo vai trò Ban kiểm định.','')}
<div class="toolbar"><div class="filter-row"><b>Lô đang theo dõi:</b>${selectLots()}</div><div class="filter-row">${roleSelect()}</div></div><div class="two-col"><section class="surface"><h2>Tiếp nhận phản ánh</h2><form id="complaint-form" class="forms"><div class="fields"><label class="field"><span>Mã SMKD (nếu có)</span><input class="input" name="code" value="${esc(l.certificate?.code||'')}" placeholder="SMKD-L001-..."/></label><label class="field"><span>Mã lô trên bao bì</span><input class="input" name="printed" value="${esc(l.id)}"/></label></div><label class="field"><span>Mô tả bất thường *</span><textarea class="input" name="text" required minlength="10" placeholder="Ví dụ: Rau có mùi lạ, niêm phong bị rách...">Sản phẩm có mùi lạ, bao bì bị rách và cần kiểm tra chất lượng.</textarea></label><div class="actions"><button class="btn primary" type="submit">＋ Gửi phản ánh</button></div></form><div class="divider"></div><h2>Kết quả truy vết lô ${esc(l.id)}</h2><form id="new-meal-form" class="forms"><div class="fields"><label class="field"><span>Tên mẻ ăn sử dụng lô này</span><input required name="name" class="input" minlength="3" placeholder="Suất ăn trưa"/></label><label class="field"><span>Số suất</span><input required name="servings" class="input" type="number" min="1" max="1000000" value="50"/></label><label class="field"><span>Lượng nguyên liệu từ lô (${esc(l.unit)})</span><input required name="amount" class="input" type="number" min="0.01" step="0.01" value="5"/></label></div><button type="submit" class="btn small">＋ Liên kết mẻ ăn với ${esc(l.id)}</button></form><div class="notice">${r.length?`Lô này liên quan <b>${r.length} mẻ ăn</b>. Cần đối chiếu danh sách phân phối thực tế trước khi quyết định thu hồi.`:'Chưa có mẻ ăn được liên kết trong bộ dữ liệu mẫu.'}</div>${r.map(m=>`<div class="muted-panel" style="margin:7px 0"><b>${esc(m.id)} · ${esc(m.name)}</b><p>${m.servings} suất ăn · Liên kết nguyên liệu ${esc(l.id)}</p></div>`).join('')}</section><section class="surface"><div class="section-head"><h2>Quản lý sự cố</h2>${l.held?badge('held'):badge(l.certificate?'valid':'pending')}</div><p>Chỉ vai trò Ban kiểm định được ghi quyết định tạm giữ. Nhật ký lưu thời gian và lý do.</p>${l.held?`<div class="notice danger"><b>Lô đang tạm giữ</b><p>${esc(l.held.reason)} · ${fmt(l.held.time)}</p></div>`:btn('⏸ Ra quyết định tạm giữ','hold','','danger')}<div class="divider"></div><h3>Phản ánh đã tiếp nhận (${db.complaints.filter(c=>c.lot===l.id).length})</h3>${db.complaints.filter(c=>c.lot===l.id).slice().reverse().map(c=>`<div class="muted-panel" style="margin:8px 0"><b>${esc(c.id)} · ${esc(c.classification)}</b><p>${esc(c.body)}</p><div class="micro">${fmt(c.time)} · Bao bì ${esc(c.printed||'không có mã')}</div></div>`).join('')||'<div class="empty">Chưa có phản ánh.</div>'}</section></div>`);}
function renderAudit(){layout(`${heading('AUDIT TRAIL','Nhật ký nghiệp vụ','Lịch sử được giữ lại trong bộ nhớ trình duyệt: kết quả không đạt, kiểm định lại, bàn giao, phân tích, cấp mã, phản ánh và tạm giữ.','')}
<section class="surface"><div class="section-head"><h2>${db.audit.length} sự kiện đã ghi</h2>${btn('Xuất JSON dữ liệu demo','export-json')}</div>${db.audit.length?db.audit.map(x=>`<div class="audit-row"><span class="micro">${fmt(x.time)}</span><b>${esc(x.type)}</b><span>${esc(x.lot)} · ${esc(x.message)} <small class="micro">(${esc(x.actor)})</small></span></div>`).join(''):'<div class="empty">Chưa có sự kiện.</div>'}</section>`);}
function renderWallet(){layout(`${heading('WEB3 AUTHENTICATION','Ví MetaMask & chứng cứ số','Kết nối ví EVM thật, đọc địa chỉ và ký thông điệp. Đây không phải giao dịch on-chain hoặc chứng nhận do cơ quan kiểm định ký.','')}
<div class="two-col"><section class="surface"><h2>01. Kết nối ví</h2><p>Dùng MetaMask trên HTTPS. Không bao giờ nhập khóa riêng hoặc cụm từ khôi phục vào website.</p><div class="notice">Trạng thái: <b>${wallet?.address?esc(wallet.address):'Chưa kết nối'}</b></div><div class="actions">${btn('⬡ Kết nối MetaMask','wallet-connect','','primary')}${btn('Ký thông điệp gắn mã lô','wallet-sign')}</div></section><section class="surface"><h2>02. Giới hạn xác thực</h2><p>Chữ ký cá nhân chứng minh ví đã chấp thuận một thông điệp, nhưng chưa định danh cá nhân hoặc tổ chức kiểm định. Hợp đồng Sepolia cần triển khai và xác minh riêng trước khi được giới thiệu là on-chain.</p><div id="wallet-status" class="muted-panel">Chưa có chữ ký.</div></section></div>`);}
function render(){if(!PAGES[page])page='overview';try{({overview:renderOverview,lots:renderLots,workflow:renderWorkflow,ai:renderAI,passports:renderPassports,incidents:renderIncidents,audit:renderAudit,wallet:renderWallet}[page])()}catch(e){console.error(e);$('#app').innerHTML=`<div class="surface"><h2>Không hiển thị được trang</h2><p>${esc(e.message)}</p><button class="btn" data-action="goto" data-id="overview">Trở về tổng quan</button></div>`}}
function modal(title,content){$('#overlay').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><div class="eyebrow">SAFEMEAL V5</div><h2>${esc(title)}</h2></div>${btn('✕','close','','small')}</div>${content}</div></div>`}
function inspectModal(){const l=getLot(),step=nextStep(l),previous=lastAttempt(l,step);if(step>3)throw Error('Đã hoàn tất ba bước.');if(role!==STEP_ROLE[step])throw Error('Cần chọn vai trò '+ROLES[STEP_ROLE[step]]);if(step===3&&!l.handoff)throw Error('Điểm bán chưa xác nhận nhận hàng.');modal('Ghi phiếu kiểm định — Bước '+step,`<div class="notice"><b>${esc(l.name)} · ${esc(STEPS[step])}</b>${previous?.result==='fail'?`<p style="color:#a14032">Kiểm định lại sau khi không đạt. Bắt buộc nêu biện pháp khắc phục.</p>`:''}</div><form class="forms" id="inspect-form"><input type="hidden" name="step" value="${step}"><div class="fields"><label class="field"><span>Địa điểm kiểm định</span><input required class="input" name="location" value="${step===1?esc(l.origin):step===2?'Xưởng GreenFood':'Quầy nhận hàng – Căng tin Đại học'}"></label><label class="field"><span>Kết quả</span><select class="input" name="result"><option value="pass">ĐẠT</option><option value="fail">KHÔNG ĐẠT (trả hồ sơ)</option></select></label></div><label class="field"><span>Nội dung kiểm tra / chứng từ</span><textarea required minlength="5" name="notes" class="input" placeholder="Viết kết quả thực tế, chứng từ đã đối chiếu...">Đã đối chiếu chứng từ, kiểm tra ngoại quan và điều kiện bảo quản.</textarea></label>${step===2?`<label class="field"><span>Hạn sử dụng</span><input required class="input" type="date" name="expiry" value="2027-12-31"></label>`:''}${step===3?`<div class="fields"><label class="field"><span>Nhiệt độ đo thực tế (°C)</span><input required class="input" type="number" step="0.1" name="temperature" value="${Math.min(4,l.threshold-1)}"></label><label class="field"><span>Niêm phong</span><select class="input" name="seal"><option value="intact">Còn nguyên</option><option value="broken">Bị rách / mở</option></select></label></div>`:''}${previous?.result==='fail'?`<label class="field"><span>Biện pháp khắc phục trước khi kiểm định lại *</span><textarea class="input" name="correction" required minlength="12" placeholder="Ví dụ: Đã thay bao bì, kiểm tra lại hồ sơ và nhiệt độ trước khi ghi phiếu mới."></textarea></label>`:''}<div class="actions"><button type="submit" class="btn primary">✓ Ghi phiếu và lưu lịch sử</button>${btn('Hủy','close')}</div></form>`);}
function lotModal(){modal('Tạo lô mới – dùng được trong tất cả chức năng',`<form id="new-lot-form" class="forms"><div class="fields"><label class="field"><span>Mã lô</span><input class="input" required name="id" placeholder="L005 / TRAI-2026-01" minlength="2" maxlength="30" pattern="[A-Za-z0-9_-]+"></label><label class="field"><span>Tên sản phẩm</span><input class="input" required name="name" placeholder="Rau cải hữu cơ" minlength="2" maxlength="110"></label><label class="field"><span>Xuất xứ</span><input class="input" required name="origin" placeholder="Lâm Đồng"></label><label class="field"><span>Số lượng</span><input class="input" required type="number" min="0.01" step="0.01" name="qty" value="40"></label><label class="field"><span>Đơn vị</span><select class="input" name="unit"><option value="kg">kg</option><option value="lít">lít</option><option value="thùng">thùng</option></select></label><label class="field"><span>Ngưỡng nhiệt độ °C</span><input class="input" required type="number" step="0.1" name="threshold" value="8"></label></div><div class="notice"><b>Sau khi tạo:</b> hệ thống mở Quản lý lô và tô màu hồ sơ mới. Nhấn 'Kiểm định' tại hàng đó để thực hiện bước 1. Không cần khởi tạo lại dữ liệu mẫu.</div><button class="btn primary" type="submit">＋ Tạo và bắt đầu kiểm định</button></form>`)}
function download(filename,blob){const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function qrGenerate({auto=false}={}){const l=getLot();if(!l.certificate)return;if(auto&&latestPassport?.code===l.certificate.code&&$('#qr-output')?.dataset.ready==='yes')return;try{let pp=await createPassport(l);latestPassport=pp;const svg=qrSVG(pp.url),target=$('#qr-output');if(target){target.dataset.ready='yes';target.innerHTML=`<div class="qr-frame" id="actual-qr">${svg}</div><p class="links-line">${esc(pp.url.slice(0,130))}...</p><div class="file-status">✓ QR mang thông tin sản phẩm, 3 phiếu và mã SMKD (gói dữ liệu tự chứa). Quét bằng camera điện thoại để kiểm tra.</div>`}if(!auto)showToast('Đã tạo QR. Hãy dùng điện thoại khác quét để mở hộ chiếu.')}catch(e){console.error('qr',e);let target=$('#qr-output');if(target)target.innerHTML=`<div class="notice danger">Không tạo được QR: ${esc(e.message)}. Vẫn có thể sao chép link sau khi tối ưu dữ liệu.</div>`;if(!auto)showToast(e.message,true)}}
async function onAction(cmd,id){const l=getLot();switch(cmd){case 'goto':page=id;render();break;case 'begin-demo':chooseLot('L003','workflow');role='farm';render();break;case 'open-lot':chooseLot(id,'workflow');break;case 'lot-to-ai':chooseLot(id,'ai');break;case 'lot-to-passport':chooseLot(id,'passports');break;case 'lot-to-incident':chooseLot(id,'incidents');break;case 'set-role':role=id;render();showToast('Đã chuyển vai trò: '+ROLES[id]);break;case 'inspect':inspectModal();break;case 'new-lot':lotModal();break;case 'import-json':{const el=document.createElement('input');el.type='file';el.accept='.json,application/json';el.onchange=async()=>{try{const f=el.files?.[0];if(!f)return;if(f.size>3*1024*1024)throw Error('File sao lưu quá lớn (>3 MB).');const data=JSON.parse(await f.text());if(data.version!==5||!Array.isArray(data.lots)||!Array.isArray(data.audit)||!Array.isArray(data.complaints)||!Array.isArray(data.meals))throw Error('Không đúng định dạng SafeMeal V5.');if(data.lots.length>1000||data.lots.some(x=>!x.id||!x.name||!Array.isArray(x.inspections)||!Array.isArray(x.aiReports)))throw Error('Danh sách lô không hợp lệ.');const ids=data.lots.map(x=>x.id);if(new Set(ids).size!==ids.length)throw Error('Bản sao lưu có mã lô trùng.');if(!confirm('Nhập bản sao lưu sẽ THAY dữ liệu hiện tại trong trình duyệt. Tiếp tục?'))return;db=data;activeLot=byId(data.active)?data.active:data.lots[0].id;resetAnalysis(getLot());save();page='lots';render();showToast('Đã nạp '+db.lots.length+' lô từ bản sao lưu.')}catch(e){showToast('Không thể nhập JSON: '+e.message,true)}};el.click();break}case 'close':$('#overlay').innerHTML='';break;case 'handoff':{handoff(l,role);audit(db,'HANDOVER',l.id,'Điểm bán đã nhận lô.',role);save();render();showToast('Đã nhận hàng. Tiếp theo lưu báo cáo AI rồi thực hiện bước 3.');break}
case 'sample':aiCSV=aiSeriesFor(l,id);aiSrc='Mẫu hệ thống theo ngưỡng '+l.threshold+'°C · '+l.id;aiResult=null;render();break;
case 'image-demo':{if(!['L003','L004'].includes(l.id))throw Error('Lô mới không có ảnh mẫu phù hợp. Hãy chọn ảnh thật của sản phẩm ở mục tải ảnh; SafeMeal sẽ không dùng nhầm ảnh cà rốt/sữa.');const fileName=id==='label'?(l.id==='L004'?'milk-label.png':'carrot-label.png'):(l.id==='L004'?'milk-main.jpg':'carrot-main.jpg');const path='assets/'+fileName;const response=await fetch(path);if(!response.ok)throw Error('Không tải được ảnh mẫu. Hãy dùng file trong thư mục assets hoặc ZIP.');const blob=await response.blob(),f=new File([blob],fileName,{type:blob.type||'image/jpeg'});imageFile(f,'photo');break}
case 'demo-csv':download(l.id+'_chuoi_nhiet_mau.csv',new Blob([aiCSV],{type:'text/csv;charset=utf-8'}));break;
case 'ai-run':{aiCSV=$('#csv-text').value;aiResult=analyzeTemperature(aiCSV,l.threshold);render();showToast('Đã phân tích dữ liệu CSV: '+aiResult.data.length+' mốc đo.');break}
case 'ai-nlp':aiNarrative=$('#ai-narrative').value;aiNLP=classifyComplaint(aiNarrative);render();break;
case 'nlp-example':aiNarrative='Mã QR không khớp mã lô trên nhãn bao bì, nghi ngờ nhầm hàng';aiNLP=null;render();break;
case 'ocr-right':aiOCR=matchOCR(l.name+' '+l.id+' NSX 22/10/2026',l);render();break;
case 'ocr-wrong':aiOCR=matchOCR(l.name+' SAI-MA NSX 22/10/2026',l);render();break;
case 'ai-save':{if(!aiResult)throw Error('Cần chạy phân tích chuỗi nhiệt trước khi lưu.');const stage=Math.min(3,nextStep(l));if(stage===3&&!l.handoff)throw Error('Phải nhận hàng trước khi lập báo cáo AI bước 3.');const seriesHash=await sha256(aiCSV),summary=fuseEvidence({cold:aiResult,ocr:aiOCR,nlp:aiNLP,similarity:aiModelResult?.similarity??null}),item={id:makeId('AI'),stage,created:iso(),risk:summary,evidence:{sensor:{count:aiResult.data.length,source:aiSrc,hash:seriesHash},ocr:aiOCR?{lotMatch:aiOCR.match,found:aiOCR.found}:null,nlp:aiNLP?{kind:aiNLP.kind,confidence:aiNLP.confidence}:null,vision:aiModelResult?{title:aiModelResult.title,similarity:aiModelResult.similarity??null}:null},source:aiSrc==='nhập tay'?'manual_input':aiSrc.startsWith('CSV')?'uploaded_csv':'sample',sourceLabel:aiSrc,series:aiCSV,seriesHash,review:null};l.aiReports.push(item);audit(db,'AI_REPORT',l.id,'Báo cáo chuỗi lạnh '+aiResult.level+'; nguồn: '+aiSrc,role);save();render();showToast('Đã lưu AI cho '+l.id+'. Quay lại Kiểm định 3 bước để hoàn tất bước 3.');break}
case 'ai-review':{if(role!=='inspector')throw Error('Chỉ Ban kiểm định được xem xét báo cáo AI.');const r=l.aiReports.at(-1);if(!r)throw Error('Lô chưa có báo cáo AI.');if(r.review)throw Error('Báo cáo đã được ghi xem xét.');const note=prompt('Nêu bằng chứng và quyết định sau khi kiểm tra thực tế (ít nhất 20 ký tự):');if(note===null)return;if(note.trim().length<20)throw Error('Cần giải thích tối thiểu 20 ký tự.');r.review={by:'inspector',time:iso(),notes:note.trim()};audit(db,'AI_REVIEW',l.id,'Ban kiểm định xem xét AI có lý do',role);save();render();showToast('Đã lưu ý kiến xem xét của Ban kiểm định.');break}
case 'qr-generate':await qrGenerate();break;
case 'qr-download':{if(!latestPassport||latestPassport.code!==l.certificate?.code)await qrGenerate();const svg=$('#actual-qr')?.innerHTML;if(!svg)throw Error('Chưa tạo được QR.');download('SafeMeal_'+l.id+'_QR.svg',new Blob([svg],{type:'image/svg+xml'}));break}
case 'copy-link':{if(!latestPassport||latestPassport.code!==l.certificate?.code)await qrGenerate();if(!latestPassport)throw Error('Chưa tạo được link.');await navigator.clipboard.writeText(latestPassport.url);showToast('Đã sao chép đường dẫn hộ chiếu.');break}
case 'copy-code':{if(!l.certificate)throw Error('Chưa có mã');await navigator.clipboard.writeText(l.certificate.code);showToast('Đã sao chép mã SMKD.');break}
case 'open-passport':{if(!latestPassport||latestPassport.code!==l.certificate?.code)await qrGenerate();if(!latestPassport)throw Error('Chưa tạo được hộ chiếu');window.open(latestPassport.url,'_blank','noopener');break}
case 'hold':{if(role!=='inspector')throw Error('Chỉ Ban kiểm định được tạm giữ. Hãy đổi vai trò ở đầu trang.');let reason=prompt('Lý do tạm giữ lô '+l.id+' (ít nhất 12 ký tự):');if(reason===null)return;setHold(l,reason,role);latestPassport=null;audit(db,'LOT_HELD',l.id,reason,role);save();render();showToast('Đã tạm giữ lô. Trạng thái trình duyệt đã cập nhật.');break}
case 'export-json':download('SafeMeal_V5_demo_export.json',new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));break;
case 'wallet-connect':{if(!window.ethereum)throw Error('Không phát hiện MetaMask. Cài extension rồi thử lại.');const accounts=await window.ethereum.request({method:'eth_requestAccounts'});const chain=await window.ethereum.request({method:'eth_chainId'});wallet={address:accounts[0],chain};render();showToast('Đã kết nối ví '+wallet.address.slice(0,10)+'…');break}
case 'wallet-sign':{if(!wallet)throw Error('Kết nối ví trước khi ký.');const message=`SafeMeal V5 DEMO\nWallet: ${wallet.address}\nLot: ${l.id}\nCertificate: ${l.certificate?.code||'(chưa có)'}\nNonce: ${crypto.randomUUID()}\nNotice: This is a learning demo, not a government certification.`;const sig=await window.ethereum.request({method:'personal_sign',params:[message,wallet.address]});$('#wallet-status').innerHTML=`<b>Đã ký thông điệp mẫu</b><div class="mono" style="font-size:10px">${esc(sig)}</div>`;break}
case 'reset':{if(confirm('Khôi phục dữ liệu mẫu? Các phiếu bạn đã nhập sẽ bị xóa khỏi trình duyệt này.')){db=seed();await seedCertified(db);save();page='overview';activeLot='L003';aiResult=null;render();showToast('Đã tạo lại dữ liệu mẫu.')}break}
default:throw Error('Chức năng không tồn tại: '+cmd)} }
async function handleForm(form){const obj=Object.fromEntries(new FormData(form));if(form.id==='new-lot-form'){const l=makeLot(obj);if(byId(l.id))throw Error('Mã lô đã tồn tại.');const previous={active:activeLot,last:db.lastCreatedLot,audit:db.audit.length};db.lots.unshift(l);activeLot=l.id;db.active=l.id;db.lastCreatedLot=l.id;role='farm';page='lots';resetAnalysis(l);audit(db,'LOT_CREATED',l.id,'Tạo lô mới và lưu hồ sơ để tiếp tục kiểm định',role);if(!save()){db.lots.shift();db.audit.splice(0,db.audit.length-previous.audit);db.lastCreatedLot=previous.last;activeLot=previous.active;db.active=previous.active;throw Error('Không lưu được lô mới. Kiểm tra quyền lưu trữ của trình duyệt; dữ liệu chưa được xác nhận thành công.')}try{sessionStorage.setItem('safemeal_v5_active',l.id)}catch(e){console.warn('Session storage unavailable',e)}$('#overlay').innerHTML='';render();showToast('ĐÃ LƯU LÔ '+l.id+' — xuất hiện trong Quản lý lô. Nhấn Kiểm định để tiếp tục.');return}
if(form.id==='inspect-form'){const l=getLot();const item=await inspect(l,{...obj,actor:role});audit(db,item.result==='pass'?'INSPECTION_PASS':'INSPECTION_FAILED',l.id,`Bước ${item.step} ${item.result==='pass'?'Đạt':'Không đạt'}${item.correction?' sau khắc phục: '+item.correction:''}`,role);if(item.step===3&&item.result==='pass'){const cert=await issueCertificate(l);audit(db,'CERT_ISSUED',l.id,'Đã cấp '+cert.code,role)}save();$('#overlay').innerHTML='';render();showToast(item.result==='fail'?`Bước ${item.step} không đạt. Đã trả về đơn vị phụ trách để khắc phục.`:`Đã lưu bước ${item.step}. ${item.step===3?'Mã QR đã sẵn sàng.':''}`);return}
if(form.id==='new-meal-form'){const l=getLot(),name=clean(obj.name),servings=Number(obj.servings),amount=Number(obj.amount);if(name.length<3||!Number.isInteger(servings)||servings<1||servings>1000000||!Number.isFinite(amount)||amount<=0||amount>l.qty)throw Error('Tên mẻ, số suất hoặc lượng nguyên liệu không hợp lệ.');const meal={id:makeId('M'),name,servings,ingredients:[{lot:l.id,qty:amount}],time:iso()};db.meals.push(meal);audit(db,'MEAL_LINKED',l.id,'Liên kết mẻ '+meal.id+': '+name,role);save();render();showToast('Đã liên kết '+meal.id+' với '+l.id);return}if(form.id==='complaint-form'){const l=getLot(),body=clean(obj.text);const registered=db.lots.find(x=>x.certificate?.code===clean(obj.code).toUpperCase());if(registered&&registered.id!==l.id)throw Error('Mã SMKD thuộc lô '+registered.id+'. Hãy chuyển đến đúng lô trước khi gửi phản ánh.');if(body.length<10)throw Error('Nhập mô tả ít nhất 10 ký tự.');const c={id:makeId('PA'),lot:l.id,body,code:clean(obj.code),printed:clean(obj.printed),classification:classifyComplaint(body).name,time:iso()};db.complaints.push(c);audit(db,'COMPLAINT',l.id,`Đã tiếp nhận ${c.id}: ${c.classification}`,'consumer');save();render();showToast('Đã ghi phản ánh '+c.id);return}}
function bytes2human(size){return (size/1024).toFixed(1)+' KB'}
function imageFile(file,target){if(!file)return;if(file.size>7*1024*1024)throw Error('Ảnh tối đa 7MB.');if(!/^image\//.test(file.type))throw Error('Chỉ chấp nhận ảnh.');const x={name:file.name,size:file.size,url:URL.createObjectURL(file),file};if(target==='photo'){if(aiImage?.url)URL.revokeObjectURL(aiImage.url);aiImage=x}else{if(aiRef?.url)URL.revokeObjectURL(aiRef.url);aiRef=x}aiModelResult=null;aiOCR=null;render();showToast('Đã nạp '+file.name+' ('+bytes2human(file.size)+')')}
async function loadScript(url,key){if(window[key])return;await new Promise((resolve,reject)=>{const old=[...document.scripts].find(x=>x.src===url);if(old){old.addEventListener('load',resolve,{once:true});old.addEventListener('error',()=>reject(Error('Không tải được '+key)),{once:true});return}const t=document.createElement('script');t.src=url;t.onload=resolve;t.onerror=()=>reject(Error('Không tải được '+key+' từ Internet.'));document.head.appendChild(t)})}
let mobileNet=null;
async function model(){if(mobileNet)return mobileNet;showToast('Đang tải MobileNet v2. Kết nối Internet lần đầu...');await loadScript('https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js','tf');await loadScript('https://cdn.jsdelivr.net/npm/@tensorflow-models/mobilenet@2.1.1/dist/mobilenet.min.js','mobilenet');mobileNet=await window.mobilenet.load({version:2,alpha:1});return mobileNet}
async function fileImage(file){if(!file)throw Error('Chưa chọn ảnh.');return await createImageBitmap(file)}
async function doVision(type){if(!aiImage?.file)throw Error('Chọn ảnh sản phẩm trước khi chạy AI.');const m=await model(),one=await fileImage(aiImage.file);try{if(type==='vision'){const results=await m.classify(one,3);aiModelResult={title:'Phân loại ảnh ImageNet',summary:results.map(x=>`${x.className}: ${(x.probability*100).toFixed(1)}%`).join(' · ')};}else{if(!aiRef?.file)throw Error('Chọn cả ảnh tham chiếu để so sánh.');const two=await fileImage(aiRef.file);try{const a=m.infer(one,true),b=m.infer(two,true);try{const [v1,v2]=await Promise.all([a.data(),b.data()]);let dot=0,aa=0,bb=0;for(let i=0;i<v1.length;i++){dot+=v1[i]*v2[i];aa+=v1[i]**2;bb+=v2[i]**2}let cosine=dot/Math.sqrt(aa*bb);aiModelResult={title:'Tương đồng đặc trưng',similarity:cosine,summary:`Cosine similarity: ${(cosine*100).toFixed(1)}%. Chỉ so sánh đặc trưng ảnh, không chứng minh sản phẩm thật/giả.`};}finally{a.dispose();b.dispose()}}finally{two.close()}}}finally{one.close()}render();showToast('Đã xử lý ảnh bằng MobileNet.');}
async function doOCR(){if(!aiImage?.file)throw Error('Chọn ảnh nhãn vào ô “Ảnh cần kiểm tra” trước.');showToast('Đang tải và chạy OCR...');await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js','Tesseract');let result;try{result=await window.Tesseract.recognize(aiImage.file,'vie+eng')}catch{result=await window.Tesseract.recognize(aiImage.file,'eng')}aiOCR=matchOCR(result.data.text,getLot());render();showToast('Đã đọc nhãn bằng OCR. Hãy kiểm tra lại với ảnh gốc.');}
document.addEventListener('click',async e=>{if(e.target.closest('[data-page]')){page=e.target.closest('[data-page]').dataset.page;$('#sidebar').classList.remove('open');render();return}const c=e.target.closest('[data-action]');if(!c)return;try{const a=c.dataset.action;if(a==='ai-vision'||a==='ai-compare')await doVision(a==='ai-vision'?'vision':'compare');else if(a==='ai-ocr')await doOCR();else await onAction(a,c.dataset.id||'')}catch(err){console.error(err);showToast(err.message,true)}});
document.addEventListener('submit',e=>{if(!['new-lot-form','inspect-form','new-meal-form','complaint-form'].includes(e.target.id))return;e.preventDefault();handleForm(e.target).catch(e=>{console.error(e);showToast(e.message,true)})});
document.addEventListener('change',async e=>{try{if(e.target.id==='lot-select'){chooseLot(e.target.value,page)}else if(e.target.id==='role-select'){role=e.target.value;render()}else if(e.target.id==='csv-file'&&e.target.files[0]){const f=e.target.files[0];if(f.size>30*1024)throw Error('CSV tối đa 30KB.');aiCSV=await f.text();aiSrc='CSV: '+f.name;aiResult=null;render();showToast('Đã tải '+f.name+' thành công. Hãy nhấn Phân tích.')}else if(e.target.id==='ai-photo')imageFile(e.target.files[0],'photo');else if(e.target.id==='ai-reference')imageFile(e.target.files[0],'reference')}catch(ex){showToast(ex.message,true)}});
document.addEventListener('input',e=>{if(e.target.id==='csv-text'){aiCSV=e.target.value;aiSrc='nhập tay';aiResult=null;const b=$('[data-action="ai-save"]');if(b)b.disabled=true;}if(e.target.id==='ai-narrative'){aiNarrative=e.target.value;aiNLP=null;}});
$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');
window.addEventListener('storage',e=>{if(e.key!==STORAGE||!e.newValue)return;try{const newer=JSON.parse(e.newValue);if(newer?.version===5&&Array.isArray(newer.lots)){db=newer;if(!byId(activeLot))activeLot=newer.active||newer.lots[0]?.id;render();showToast('Danh sách lô đã được đồng bộ từ tab SafeMeal khác.')}}catch(err){console.warn('Storage synchronization error',err)}});
init();
